pub fn vanilla_stat_type_by_id(id: i32) -> Option<&'static StatTypeCatalogEntry> {
    VANILLA_STAT_TYPES.get(usize::try_from(id).ok()?)
}

pub fn vanilla_stat_type_by_resource_id(
    resource_id: &str,
) -> Option<&'static StatTypeCatalogEntry> {
    VANILLA_STAT_TYPES
        .iter()
        .find(|entry| entry.resource_id == resource_id)
}

pub fn vanilla_custom_stat_by_id(id: i32) -> Option<&'static CustomStatCatalogEntry> {
    VANILLA_CUSTOM_STATS.get(usize::try_from(id).ok()?)
}

pub fn vanilla_custom_stat_by_resource_id(
    resource_id: &str,
) -> Option<&'static CustomStatCatalogEntry> {
    VANILLA_CUSTOM_STATS
        .iter()
        .find(|entry| entry.resource_id == resource_id)
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn stat_catalogs_preserve_vanilla_declaration_order() {
        assert_eq!(VANILLA_STAT_TYPES.len(), 9);
        assert_eq!(VANILLA_CUSTOM_STATS.len(), 77);
        assert_eq!(VANILLA_OBJECTIVE_CRITERIA_NAMES.len(), 43);
        let mut type_resources = HashSet::new();
        for (id, entry) in VANILLA_STAT_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(type_resources.insert(entry.resource_id));
            assert_eq!(vanilla_stat_type_by_id(entry.id), Some(entry));
        }
        let mut custom_resources = HashSet::new();
        for (id, entry) in VANILLA_CUSTOM_STATS.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(custom_resources.insert(entry.resource_id));
            assert_eq!(vanilla_custom_stat_by_id(entry.id), Some(entry));
        }
        assert_eq!(VANILLA_STAT_TYPES[0].resource_id, "minecraft:mined");
        assert_eq!(
            VANILLA_STAT_TYPES[8].value_registry,
            "minecraft:custom_stat"
        );
        assert_eq!(VANILLA_STAT_TYPE_BLOCK_MINED_ID, 0);
        assert_eq!(VANILLA_STAT_TYPE_ITEM_CRAFTED_ID, 1);
        assert_eq!(VANILLA_STAT_TYPE_ENTITY_KILLED_ID, 6);
        assert_eq!(VANILLA_STAT_TYPE_ENTITY_KILLED_BY_ID, 7);
        assert_eq!(VANILLA_STAT_TYPE_CUSTOM_ID, 8);
        assert_eq!(VANILLA_CUSTOM_STATS[0].resource_id, "minecraft:leave_game");
        assert_eq!(
            VANILLA_CUSTOM_STATS[76].resource_id,
            "minecraft:interact_with_smithing_table"
        );
        assert!(VANILLA_OBJECTIVE_CRITERIA_NAMES.contains(&"dummy"));
        assert!(VANILLA_OBJECTIVE_CRITERIA_NAMES.contains(&"teamkill.dark_blue"));
        assert!(VANILLA_OBJECTIVE_CRITERIA_NAMES.contains(&"killedByTeam.white"));
    }

    fn starts_with_integer_literal(source: &str) -> bool {
        source
            .trim_start()
            .strip_prefix('-')
            .unwrap_or(source.trim_start())
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_digit())
    }

    fn contains_numeric_stat_type_id_reference(source: &str) -> bool {
        let compact: String = source
            .chars()
            .filter(|character| !character.is_whitespace())
            .collect();
        let numeric_construction = compact.match_indices("stat_type_id:").any(|(offset, _)| {
            starts_with_integer_literal(&compact[offset + "stat_type_id:".len()..])
        });
        let numeric_field_comparison = compact.match_indices(".stat_type_id").any(|(offset, _)| {
            let suffix = &compact[offset + ".stat_type_id".len()..];
            [",", "==", "!=", "="].iter().any(|separator| {
                suffix
                    .strip_prefix(separator)
                    .is_some_and(starts_with_integer_literal)
            })
        });
        let numeric_json_comparison =
            compact
                .match_indices("[\"stat_type_id\"]")
                .any(|(offset, _)| {
                    let suffix = &compact[offset + "[\"stat_type_id\"]".len()..];
                    [",", "==", "!=", "="].iter().any(|separator| {
                        suffix
                            .strip_prefix(separator)
                            .is_some_and(starts_with_integer_literal)
                    })
                });
        let numeric_query = ["stat_value(", "stat_identity("].iter().any(|marker| {
            compact
                .match_indices(marker)
                .any(|(offset, _)| starts_with_integer_literal(&compact[offset + marker.len()..]))
        });
        let numeric_alias = source.lines().any(|line| {
            let compact: String = line
                .chars()
                .filter(|character| !character.is_whitespace())
                .collect();
            (compact.starts_with("let") || compact.starts_with("const"))
                && compact.contains("stat_type")
                && compact
                    .rsplit_once('=')
                    .is_some_and(|(_, value)| starts_with_integer_literal(value))
        });
        numeric_construction
            || numeric_field_comparison
            || numeric_json_comparison
            || numeric_query
            || numeric_alias
    }

    #[test]
    fn numeric_stat_type_guard_covers_semantic_consumers() {
        assert!(contains_numeric_stat_type_id_reference("stat_type_id: 8,"));
        assert!(contains_numeric_stat_type_id_reference(
            "assert_eq!(entry.stat_type_id, 6);"
        ));
        assert!(contains_numeric_stat_type_id_reference(
            "assert_eq!(entry[\"stat_type_id\"], 0);"
        ));
        assert!(contains_numeric_stat_type_id_reference(
            "world.stat_value(8, 10)"
        ));
        assert!(contains_numeric_stat_type_id_reference(
            "let custom_stat_type_id = 8;"
        ));
        assert!(!contains_numeric_stat_type_id_reference(
            "stat_type_id: VANILLA_STAT_TYPE_CUSTOM_ID,"
        ));
        assert!(!contains_numeric_stat_type_id_reference(
            "world.stat_identity(unknown_stat_type_id, 10)"
        ));
    }

    #[test]
    fn semantic_sources_do_not_restore_numeric_stat_type_ids() {
        fn visit(path: &Path, violations: &mut Vec<String>) {
            if path.is_dir() {
                for entry in fs::read_dir(path).unwrap() {
                    visit(&entry.unwrap().path(), violations);
                }
                return;
            }
            if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                return;
            }
            let source = fs::read_to_string(path).unwrap();
            if contains_numeric_stat_type_id_reference(&source) {
                violations.push(format!("{}: numeric StatType id reference", path.display()));
            }
        }
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let mut violations = Vec::new();
        for path in [
            crates.join("bbb-world/src"),
            crates.join("bbb-net/src"),
            crates.join("bbb-control/src"),
            crates.join("bbb-native/src"),
        ] {
            visit(&path, &mut violations);
        }
        assert!(
            violations.is_empty(),
            "semantic consumers restored numeric StatType ids:\n{}",
            violations.join("\n")
        );
    }
}
